 static List<JsonObject> Parse(string raw){
  raw=raw.Trim().TrimStart('\uFEFF');if(raw.Length==0)throw new Exception("Subscription content is empty.");
  if(raw.StartsWith("{")||raw.StartsWith("[")){
   var node=JsonNode.Parse(raw)!;var profiles=node is JsonArray array?array.Select(x=>x?.AsObject()??throw new Exception("Invalid JSON configuration.")).ToList():new(){node.AsObject()};
   if(profiles.Count==0||profiles.Any(x=>x["outbounds"] is not JsonArray))throw new Exception("Subscription does not contain Xray configurations.");return profiles;
  }
  var lines=raw.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries).Where(x=>!x.StartsWith('#')&&!x.StartsWith(';')).ToArray();
  var links=new List<string>();foreach(var line in lines){if(line.StartsWith("vless://",StringComparison.OrdinalIgnoreCase)||line.StartsWith("vmess://",StringComparison.OrdinalIgnoreCase)||line.StartsWith("trojan://",StringComparison.OrdinalIgnoreCase))links.Add(line);}
  if(links.Count>0)return links.Select(ParseProxyLink).ToList();
  try{return Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(raw.Replace('-','+').Replace('_','/').PadRight((raw.Length+3)/4*4,'='))));}catch(Exception e) when(e is FormatException or System.Text.Json.JsonException or InvalidOperationException){throw new Exception("Unsupported format; enter Xray JSON or VLESS, VMess or Trojan links.");}
 }
 static Dictionary<string,string> LinkQuery(Uri uri){var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var pair in uri.Query.TrimStart('?').Split('&',StringSplitOptions.RemoveEmptyEntries)){var parts=pair.Split('=',2);result[Uri.UnescapeDataString(parts[0].Replace('+',' '))]=parts.Length>1?Uri.UnescapeDataString(parts[1].Replace('+',' ')):"";}return result;}
 static JsonObject ParseProxyLink(string text){
