  JsonObject outbound;
  if(uri.Scheme.Equals("vless",StringComparison.OrdinalIgnoreCase)){
   var id=Uri.UnescapeDataString(uri.UserInfo);if(!Guid.TryParse(id,out _))throw new Exception("Invalid VLESS identifier.");var user=new JsonObject{["id"]=id,["encryption"]=query.GetValueOrDefault("encryption","none")};if(query.TryGetValue("flow",out var flow)&&flow.Length>0)user["flow"]=flow;
   outbound=new JsonObject{["protocol"]="vless",["settings"]=new JsonObject{["vnext"]=new JsonArray(new JsonObject{["address"]=uri.Host,["port"]=uri.Port,["users"]=new JsonArray(user)})}};
