  }else throw new Exception("Unsupported proxy link scheme.");
  var network=query.GetValueOrDefault("type",query.GetValueOrDefault("network","tcp")).ToLowerInvariant();var security=query.GetValueOrDefault("security","none").ToLowerInvariant();var stream=new JsonObject{["network"]=network,["security"]=security};
