  else if(network=="grpc"){stream["grpcSettings"]=new JsonObject{["serviceName"]=query.GetValueOrDefault("serviceName",query.GetValueOrDefault("path","")),["authority"]=query.GetValueOrDefault("authority","")};}
  else if(network=="httpupgrade"){stream["httpupgradeSettings"]=new JsonObject{["path"]=query.GetValueOrDefault("path",""),["host"]=query.GetValueOrDefault("host","")};}
  else if(network=="tcp"&&query.TryGetValue("headerType",out var header)&&header!="none")stream["tcpSettings"]=new JsonObject{["header"] = new JsonObject{["type"]=header}};
  var serverName=query.GetValueOrDefault("sni",query.GetValueOrDefault("serverName",query.GetValueOrDefault("host",uri.Host)));
  if(security=="tls"){var tls=new JsonObject{["serverName"]=serverName};if(query.TryGetValue("allowInsecure",out var insecure))tls["allowInsecure"]=insecure is "1" or "true";if(query.TryGetValue("fp",out var fingerprint))tls["fingerprint"]=fingerprint;if(query.TryGetValue("alpn",out var alpn))tls["alpn"]=new JsonArray(alpn.Split(',').Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray());stream["tlsSettings"]=tls;}
