 static async Task<List<JsonObject>> Fetch(string address){if(!Uri.TryCreate(address,UriKind.Absolute,out var u)||u.Scheme!="https")throw new Exception("Enter an HTTPS URL.");using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));using var http=new HttpClient(new HttpClientHandler{UseProxy=false}){Timeout=TimeSpan.FromSeconds(30)};http.DefaultRequestHeaders.UserAgent.ParseAdd("v2rayN/7.0");using var r=await http.GetAsync(u,HttpCompletionOption.ResponseHeadersRead,timeout.Token);r.EnsureSuccessStatusCode();using var input=await r.Content.ReadAsStreamAsync(timeout.Token);using var output=new MemoryStream();var buf=new byte[8192];int n;while((n=await input.ReadAsync(buf,timeout.Token))>0){if(output.Length+n>5000000)throw new Exception("Subscription exceeds the size limit.");output.Write(buf,0,n);}return ReadAccountHeader(r,Parse(System.Text.Encoding.UTF8.GetString(output.ToArray())));}
