 static JsonObject XConfig(JsonObject original,int port){var c=(JsonObject)original.DeepClone();c.Remove("_shareLink");c.Remove("_shareSnapshot");if(c["streamSettings"] is JsonObject legacy){if(Outbound(c) is JsonObject output&&output["streamSettings"]==null)output["streamSettings"]=legacy.DeepClone();c.Remove("streamSettings");}var tag=c["inbounds"]?.AsArray().FirstOrDefault(x=>x?["protocol"]?.ToString()=="socks")?["tag"]?.ToString()??"socks";c["inbounds"]=new JsonArray(new JsonObject{["tag"]=tag,["listen"]="127.0.0.1",["port"]=port,["protocol"]="socks",["settings"]=new JsonObject{["auth"]="noauth",["udp"]=true}});c["log"]=JsonNode.Parse("{\"loglevel\":\"warning\"}");return c;}
 static async Task<(JsonObject Config,string[] Exclusions)> Prepare(JsonObject original,int port){
  var config=XConfig(original,port);var exclusions=new HashSet<string>();
  using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(15));
  async Task<string> Resolve(string host){if(IPAddress.TryParse(host,out var literal)){exclusions.Add(literal+(literal.AddressFamily==AddressFamily.InterNetwork?"/32":"/128"));return literal.ToString();}var addresses=await Dns.GetHostAddressesAsync(host,timeout.Token);var address=addresses.FirstOrDefault(x=>x.AddressFamily==AddressFamily.InterNetwork)??addresses.FirstOrDefault()??throw new Exception("Could not resolve the server address.");exclusions.Add(address+(address.AddressFamily==AddressFamily.InterNetwork?"/32":"/128"));return address.ToString();}
  foreach(var item in config["outbounds"]!.AsArray()){
   if(item is not JsonObject outbound||outbound["settings"] is not JsonObject settings)continue;
   foreach(var key in new[]{"vnext","servers"})if(settings[key] is JsonArray endpoints)foreach(var entry in endpoints){if(entry is not JsonObject endpoint||endpoint["address"] is not JsonValue value)continue;var host=value.ToString();if(!IPAddress.TryParse(host,out _)&&outbound["streamSettings"] is JsonObject stream){var security=stream["security"]?.ToString();if(security is "tls" or "reality"){var securityKey=security+"Settings";if(stream[securityKey] is not JsonObject)stream[securityKey]=new JsonObject();var options=stream[securityKey]!.AsObject();if(string.IsNullOrWhiteSpace(options["serverName"]?.ToString()))options["serverName"]=host;}}endpoint["address"]=await Resolve(host);}
