 async Task Connect(){if(busy||updating||xray!=null)return;if(servers.SelectedIndices.Count==0){MessageBox.Show(L("Select a server first.","یک سرور انتخاب کنید."));return;}if(tun.Checked&&!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)){MessageBox.Show(L("Run this app as administrator to use TUN.","برای TUN برنامه را با Run as administrator باز کنید."));return;}activeProfileKey=ProfileKey(Profiles[(int)servers.SelectedItems[0].Tag!]);busy=true;SetControls();details.Clear();string stage=L("Starting Xray","راه‌اندازی Xray");status.Text=stage+"…";logs.Clear();
