 void Disconnect(){foreach(var p in new[]{box,xray}){if(p==null)continue;try{if(!p.HasExited){p.Kill(true);p.WaitForExit(4000);}}catch{}p.Dispose();}box=null;xray=null;if(session!=null){try{Directory.Delete(session,true);}catch{}session=null;}status.Text=L("Disconnected","قطع است");SetControls();}
 public static int Validate(string file){SubscriptionStore.SelfTest();var profiles=Parse(File.ReadAllText(file));var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".json");int errors=0;try{foreach(var c in profiles){var prepared=Prepare(c,17890).GetAwaiter().GetResult();File.WriteAllText(path,prepared.Config.ToJsonString());if(Check("xray.exe",path,"run","-test")!=0)errors++;var tc=TConfig(17890);tc["inbounds"]![0]!["route_exclude_address"]=new JsonArray(prepared.Exclusions.Select(x=>(JsonNode?)JsonValue.Create(x)).ToArray());File.WriteAllText(path,tc.ToJsonString());if(Check("sing-box.exe",path,"check")!=0)errors++;}File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"validation.txt"),$"Profiles: {profiles.Count}; Xray and TUN config failures: {errors}; encrypted persistence roundtrip: passed");}finally{File.Delete(path);}return errors;}
 public static async Task<int> NetworkCheck(string file){var profiles=Parse(File.ReadAllText(file));var reports=new List<string>();int errors=0;using var job=new CoreJob();foreach(var index in new[]{0,5,10}.Where(i=>i<profiles.Count)){var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".json");Process? p=null;try{var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();var prepared=await Prepare(profiles[index],port);File.WriteAllText(path,prepared.Config.ToJsonString());var si=new ProcessStartInfo(Core("xray.exe")){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(Core("xray.exe")),ArgumentList={"run","-c",path}};p=Process.Start(si)!;job.Add(p);await Task.Delay(700);bool ok=!p.HasExited&&await Probe(port);if(!ok)errors++;reports.Add($"Profile {index}: HTTPS through prepared SOCKS config = {ok}");}catch(Exception e){errors++;reports.Add($"Profile {index}: {SafeError(e.Message)}");}finally{if(p!=null){try{if(!p.HasExited){p.Kill(true);p.WaitForExit(4000);}}catch{}p.Dispose();}File.Delete(path);}}File.WriteAllLines(Path.Combine(AppContext.BaseDirectory,"network-check.txt"),reports);return errors;}
 static int Check(string core,string path,params string[] args){var info=new ProcessStartInfo(Core(core)){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(Core(core))};foreach(var a in args)info.ArgumentList.Add(a);info.ArgumentList.Add("-c");info.ArgumentList.Add(path);using var p=Process.Start(info)!;p.WaitForExit();return p.ExitCode;}
}
